                                r_list_free (l);
                        }
                }
        }
        if (bin->filter_rules & R_BIN_REQ_STRINGS) {
                if (cp->strings) {
                        o->strings = cp->strings (binfile);
                } else {
                        o->strings = r_bin_file_get_strings (binfile, minlen, 0, binfile->rawstr);
                }
                if (bin->debase64) {
                        r_bin_object_filter_strings (o);
                }
                REBASE_PADDR (o, o->strings, RBinString);
        }
